{
  "name": "Reliability Golden Source Generator",
  "description": "An expert tool for Reliability Engineers to generate standardized, ISO-aligned encyclopedia entries for Vector Database ingestion using Gemini 3."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface GenerationRequest {
  term: string;
  draftDefinition: string;
}

export interface GenerationResponse {
  content: string;
  error?: string;
}

export enum GeneratorStatus {
  IDLE = 'IDLE',
  GENERATING = 'GENERATING',
  SUCCESS = 'SUCCESS',
  ERROR = 'ERROR'
}

export interface HistoryItem {
  id: string;
  term: string;
  timestamp: number;
  content: string;
}

import { GoogleGenAI } from "@google/genai";
import { GenerationRequest } from '../types';

const MODEL_NAME = "gemini-3-pro-preview";

export const generateEncyclopediaEntry = async (request: GenerationRequest): Promise<string> => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) {
    throw new Error("API Key is missing. Please ensure process.env.API_KEY is available.");
  }

  const ai = new GoogleGenAI({ apiKey });

  const systemInstruction = `
    Role: You are an Expert Maintenance & Reliability Engineer and Technical Data Architect.
    Task: specific glossary term and a brief input definition, generate a "Golden Source" encyclopedia entry suitable for a Vector Database ingestion pipeline.
    Tone: Technical, authoritative, ISO-standard aligned, and concise.

    Format Requirements (STRICT):
    1. YAML Frontmatter: Must be the very first block.
       - id: Create a deterministic ID (e.g., term-cavitation or term-asset). Do not use random numbers.
       - term: The exact term.
       - synonyms: A list of 3-5 alternative words users might search for.
       - tags: Taxonomy tags (e.g., "Reliability", "Inventory", "ISO 55000").
       - related_terms: A list of IDs for related concepts if known, or just the terms.
       - last_updated: Current date YYYY-MM-DD.
    2. Document Title: The first line of the text body must be the term itself as a Level 1 Header (e.g., # Asset).
    3. Section Headers: All subsequent sections must be Level 2 Headers (##).

    Required Sections:
    1. # [Term Name]
    2. ## Definition: A precise, standard definition (referencing ISO standards if applicable).
    3. ## Detailed Explanation: Technical context, how it functions, or its role in a facility.
    4. ## Key Data Attributes: (Crucial) List the specific data fields a reliability engineer would track for this term (e.g., "Install Date", "Serial Number", "MTBF", "P-F Interval").
    5. ## Failure Modes & Risks: How this concept fails or the risks associated with mismanaging it.
    6. ## Best Practices: Bulleted actionable advice.

    Output: Produce only the Markdown. No conversational filler.
  `;

  const prompt = `
    Term: ${request.term}
    Draft Definition: ${request.draftDefinition}
  `;

  try {
    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: prompt,
      config: {
        systemInstruction: systemInstruction,
        temperature: 0.2, // Low temperature for factual, authoritative output
        topK: 40,
        topP: 0.95,
      }
    });

    if (response.text) {
      return response.text;
    } else {
      throw new Error("Empty response from Gemini.");
    }
  } catch (error: any) {
    console.error("Gemini Generation Error:", error);
    throw new Error(error.message || "Failed to generate content.");
  }
};

import React from 'react';

interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'secondary' | 'ghost';
  isLoading?: boolean;
  icon?: React.ReactNode;
}

export const Button: React.FC<ButtonProps> = ({ 
  children, 
  variant = 'primary', 
  isLoading, 
  icon, 
  className = '', 
  disabled,
  ...props 
}) => {
  const baseStyles = "inline-flex items-center justify-center px-4 py-2 rounded-md font-medium transition-colors focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-offset-slate-900 disabled:opacity-50 disabled:cursor-not-allowed";

  const variants = {
    primary: "bg-blue-600 hover:bg-blue-500 text-white focus:ring-blue-500",
    secondary: "bg-slate-700 hover:bg-slate-600 text-slate-100 focus:ring-slate-500",
    ghost: "bg-transparent hover:bg-slate-800 text-slate-300 hover:text-white focus:ring-slate-500"
  };

  return (
    <button 
      className={`${baseStyles} ${variants[variant]} ${className}`}
      disabled={disabled || isLoading}
      {...props}
    >
      {isLoading ? (
        <svg className="animate-spin -ml-1 mr-2 h-4 w-4 text-current" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
          <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
          <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
        </svg>
      ) : icon ? (
        <span className="mr-2">{icon}</span>
      ) : null}
      {children}
    </button>
  );
};

import React, { useState } from 'react';
import { Button } from './Button';
import { Copy, Download, Check } from 'lucide-react';

interface OutputDisplayProps {
  content: string;
  term: string;
}

export const OutputDisplay: React.FC<OutputDisplayProps> = ({ content, term }) => {
  const [copied, setCopied] = useState(false);

  const handleCopy = async () => {
    try {
      await navigator.clipboard.writeText(content);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch (err) {
      console.error('Failed to copy text: ', err);
    }
  };

  const handleDownload = () => {
    const element = document.createElement("a");
    const file = new Blob([content], {type: 'text/markdown'});
    element.href = URL.createObjectURL(file);
    // Sanitize term for filename
    const filename = term.toLowerCase().replace(/[^a-z0-9]/g, '-') + '.md';
    element.download = filename;
    document.body.appendChild(element); 
    element.click();
    document.body.removeChild(element);
  };

  return (
    <div className="flex flex-col h-full bg-slate-900 rounded-lg border border-slate-700 overflow-hidden shadow-xl">
      <div className="flex items-center justify-between px-4 py-3 bg-slate-800 border-b border-slate-700">
        <h3 className="text-sm font-semibold text-slate-300 uppercase tracking-wider">
          Generated Output
        </h3>
        <div className="flex gap-2">
          <Button 
            variant="ghost" 
            size="sm" 
            onClick={handleCopy} 
            className="text-xs px-2 py-1"
            title="Copy to Clipboard"
          >
            {copied ? <Check size={16} className="text-green-400" /> : <Copy size={16} />}
          </Button>
          <Button 
            variant="ghost" 
            size="sm" 
            onClick={handleDownload} 
            className="text-xs px-2 py-1"
            title="Download .md file"
          >
            <Download size={16} />
          </Button>
        </div>
      </div>
      <div className="flex-1 overflow-auto p-0 relative group">
        <pre className="p-4 text-sm font-mono text-slate-300 leading-relaxed whitespace-pre-wrap h-full">
          {content}
        </pre>
      </div>
    </div>
  );
};

import React, { useState, useCallback } from 'react';
import { generateEncyclopediaEntry } from './services/geminiService';
import { GeneratorStatus, HistoryItem } from './types';
import { Button } from './components/Button';
import { OutputDisplay } from './components/OutputDisplay';
import { Database, Zap, BookOpen, AlertCircle, History } from 'lucide-react';

const App: React.FC = () => {
  const [term, setTerm] = useState('');
  const [draftDefinition, setDraftDefinition] = useState('');
  const [status, setStatus] = useState<GeneratorStatus>(GeneratorStatus.IDLE);
  const [result, setResult] = useState<string>('');
  const [error, setError] = useState<string | null>(null);
  const [history, setHistory] = useState<HistoryItem[]>([]);

  const handleGenerate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!term.trim()) return;

    setStatus(GeneratorStatus.GENERATING);
    setError(null);
    setResult('');

    try {
      const generatedContent = await generateEncyclopediaEntry({ term, draftDefinition });
      setResult(generatedContent);
      setStatus(GeneratorStatus.SUCCESS);

      // Add to history
      const newItem: HistoryItem = {
        id: Date.now().toString(),
        term: term,
        timestamp: Date.now(),
        content: generatedContent
      };
      setHistory(prev => [newItem, ...prev].slice(0, 10)); // Keep last 10
    } catch (err: any) {
      console.error(err);
      setError(err.message || "An unexpected error occurred.");
      setStatus(GeneratorStatus.ERROR);
    }
  };

  const loadFromHistory = (item: HistoryItem) => {
    setTerm(item.term);
    setResult(item.content);
    setStatus(GeneratorStatus.SUCCESS);
  };

  const clearForm = useCallback(() => {
    setTerm('');
    setDraftDefinition('');
    setStatus(GeneratorStatus.IDLE);
    setResult('');
    setError(null);
  }, []);

  return (
    <div className="min-h-screen bg-slate-950 text-slate-200 font-sans selection:bg-blue-500/30">
      {/* Header */}
      <header className="border-b border-slate-800 bg-slate-900/50 backdrop-blur-md sticky top-0 z-10">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="p-2 bg-blue-600 rounded-lg shadow-lg shadow-blue-900/20">
              <Database className="w-6 h-6 text-white" />
            </div>
            <div>
              <h1 className="text-xl font-bold text-white tracking-tight">Golden Source</h1>
              <p className="text-xs text-slate-400 font-mono uppercase tracking-widest">Reliability Data Architect</p>
            </div>
          </div>
          <div className="flex items-center gap-4">
             <div className="hidden md:flex items-center gap-2 text-xs text-slate-500 border border-slate-800 rounded-full px-3 py-1">
                <span className="w-2 h-2 rounded-full bg-green-500 animate-pulse"></span>
                System Online
             </div>
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 h-[calc(100vh-8rem)]">

          {/* Left Column: Input Form */}
          <div className="lg:col-span-4 flex flex-col gap-6 h-full overflow-y-auto pr-2 custom-scrollbar">

            <div className="bg-slate-900 rounded-xl p-6 border border-slate-800 shadow-xl">
              <div className="flex items-center gap-2 mb-6">
                <Zap className="w-5 h-5 text-amber-400" />
                <h2 className="text-lg font-semibold text-white">Definition Generator</h2>
              </div>

              <form onSubmit={handleGenerate} className="flex flex-col gap-5">
                <div>
                  <label htmlFor="term" className="block text-sm font-medium text-slate-400 mb-2">
                    Term Name <span className="text-red-400">*</span>
                  </label>
                  <input
                    type="text"
                    id="term"
                    value={term}
                    onChange={(e) => setTerm(e.target.value)}
                    placeholder="e.g. Cavitation, P-F Interval"
                    className="w-full bg-slate-800 border border-slate-700 rounded-lg px-4 py-3 text-white placeholder-slate-500 focus:ring-2 focus:ring-blue-500 focus:border-transparent transition-all outline-none"
                    required
                  />
                </div>

                <div>
                  <label htmlFor="definition" className="block text-sm font-medium text-slate-400 mb-2">
                    Draft Definition / Context
                  </label>
                  <textarea
                    id="definition"
                    value={draftDefinition}
                    onChange={(e) => setDraftDefinition(e.target.value)}
                    rows={6}
                    placeholder="Briefly describe the term. The AI will standardize it to ISO norms."
                    className="w-full bg-slate-800 border border-slate-700 rounded-lg px-4 py-3 text-white placeholder-slate-500 focus:ring-2 focus:ring-blue-500 focus:border-transparent transition-all outline-none resize-none"
                  />
                </div>

                <div className="flex gap-3 mt-2">
                  <Button 
                    type="submit" 
                    className="flex-1" 
                    isLoading={status === GeneratorStatus.GENERATING}
                    icon={<Zap size={18} />}
                  >
                    Generate Entry
                  </Button>
                  <Button 
                    type="button" 
                    variant="secondary"
                    onClick={clearForm}
                    disabled={status === GeneratorStatus.GENERATING}
                  >
                    Clear
                  </Button>
                </div>
              </form>
            </div>

            {/* History Panel */}
            {history.length > 0 && (
              <div className="bg-slate-900 rounded-xl p-6 border border-slate-800 shadow-xl flex-1 min-h-[200px]">
                <div className="flex items-center gap-2 mb-4">
                  <History className="w-5 h-5 text-slate-400" />
                  <h2 className="text-md font-semibold text-slate-200">Recent Generations</h2>
                </div>
                <ul className="space-y-2">
                  {history.map((item) => (
                    <li key={item.id}>
                      <button
                        onClick={() => loadFromHistory(item)}
                        className="w-full text-left px-3 py-2 rounded hover:bg-slate-800 transition-colors flex justify-between items-center group"
                      >
                        <span className="text-sm text-slate-300 group-hover:text-white truncate">{item.term}</span>
                        <span className="text-xs text-slate-500 font-mono">
                           {new Date(item.timestamp).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}
                        </span>
                      </button>
                    </li>
                  ))}
                </ul>
              </div>
            )}
          </div>

          {/* Right Column: Output */}
          <div className="lg:col-span-8 flex flex-col h-full">
            {error && (
              <div className="mb-4 bg-red-900/20 border border-red-800 rounded-lg p-4 flex items-start gap-3">
                <AlertCircle className="w-5 h-5 text-red-500 mt-0.5" />
                <div>
                  <h3 className="text-sm font-semibold text-red-400">Generation Failed</h3>
                  <p className="text-sm text-red-300 mt-1">{error}</p>
                </div>
              </div>
            )}

            {result ? (
              <OutputDisplay content={result} term={term} />
            ) : (
              <div className="flex-1 bg-slate-900 rounded-lg border border-slate-800 border-dashed flex flex-col items-center justify-center text-slate-500 p-12 text-center shadow-inner">
                <div className="w-16 h-16 bg-slate-800 rounded-full flex items-center justify-center mb-6">
                  <BookOpen className="w-8 h-8 text-slate-600" />
                </div>
                <h3 className="text-lg font-medium text-slate-300 mb-2">Ready to Standardize</h3>
                <p className="max-w-md">
                  Enter a maintenance term to generate a "Golden Source" record formatted for your Vector Database (RAG) pipeline.
                </p>
                <div className="mt-8 flex gap-4 text-xs font-mono text-slate-600">
                  <span className="bg-slate-800 px-2 py-1 rounded">YAML Frontmatter</span>
                  <span className="bg-slate-800 px-2 py-1 rounded">ISO 14224</span>
                  <span className="bg-slate-800 px-2 py-1 rounded">Failure Modes</span>
                </div>
              </div>
            )}
          </div>

        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useCallback, useEffect } from 'react';
import { generateEncyclopediaEntry } from './services/geminiService';
import { GeneratorStatus, HistoryItem } from './types';
import { Button } from './components/Button';
import { OutputDisplay } from './components/OutputDisplay';
import { Database, Zap, BookOpen, AlertCircle, History, Key, Info } from 'lucide-react';

const App: React.FC = () => {
  const [term, setTerm] = useState('');
  const [draftDefinition, setDraftDefinition] = useState('');
  const [status, setStatus] = useState<GeneratorStatus>(GeneratorStatus.IDLE);
  const [result, setResult] = useState<string>('');
  const [error, setError] = useState<string | null>(null);
  const [history, setHistory] = useState<HistoryItem[]>([]);
  const [hasOwnKey, setHasOwnKey] = useState<boolean>(false);

  useEffect(() => {
    const checkKey = async () => {
      if (window.aistudio?.hasSelectedApiKey) {
        const selected = await window.aistudio.hasSelectedApiKey();
        setHasOwnKey(selected);
      }
    };
    checkKey();
  }, []);

  const handleSelectKey = async () => {
    if (window.aistudio?.openSelectKey) {
      await window.aistudio.openSelectKey();
      setHasOwnKey(true);
    }
  };

  const handleGenerate = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    if (!term.trim()) return;

    setStatus(GeneratorStatus.GENERATING);
    setError(null);
    setResult('');

    try {
      const generatedContent = await generateEncyclopediaEntry({ term, draftDefinition });
      setResult(generatedContent);
      setStatus(GeneratorStatus.SUCCESS);

      const newItem: HistoryItem = {
        id: Date.now().toString(),
        term: term,
        timestamp: Date.now(),
        content: generatedContent
      };
      setHistory(prev => [newItem, ...prev].slice(0, 10));
    } catch (err: any) {
      console.error(err);
      let errorMessage = err.message || "An unexpected error occurred.";

      // Specific handling for 429 Resource Exhausted
      if (errorMessage.includes("429") || errorMessage.includes("RESOURCE_EXHAUSTED")) {
        errorMessage = "The model is currently at its capacity or rate limit. To bypass this, please use a personal API key from a paid GCP project.";
      }

      setError(errorMessage);
      setStatus(GeneratorStatus.ERROR);
    }
  };

  const loadFromHistory = (item: HistoryItem) => {
    setTerm(item.term);
    setResult(item.content);
    setStatus(GeneratorStatus.SUCCESS);
  };

  const clearForm = useCallback(() => {
    setTerm('');
    setDraftDefinition('');
    setStatus(GeneratorStatus.IDLE);
    setResult('');
    setError(null);
  }, []);

  return (
    <div className="min-h-screen bg-slate-950 text-slate-200 font-sans selection:bg-blue-500/30">
      <header className="border-b border-slate-800 bg-slate-900/50 backdrop-blur-md sticky top-0 z-10">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="p-2 bg-blue-600 rounded-lg shadow-lg shadow-blue-900/20">
              <Database className="w-6 h-6 text-white" />
            </div>
            <div>
              <h1 className="text-xl font-bold text-white tracking-tight">Golden Source</h1>
              <p className="text-xs text-slate-400 font-mono uppercase tracking-widest">Reliability Data Architect</p>
            </div>
          </div>
          <div className="flex items-center gap-4">
            <Button 
              variant={hasOwnKey ? "ghost" : "primary"} 
              size="sm" 
              onClick={handleSelectKey}
              className="text-xs h-9"
              icon={<Key size={14} />}
            >
              {hasOwnKey ? "Change API Key" : "Set Personal Key"}
            </Button>
            <div className="hidden md:flex items-center gap-2 text-xs text-slate-500 border border-slate-800 rounded-full px-3 py-1">
              <span className={`w-2 h-2 rounded-full ${status === GeneratorStatus.GENERATING ? 'bg-amber-500 animate-pulse' : 'bg-green-500'}`}></span>
              {status === GeneratorStatus.GENERATING ? 'Processing...' : 'System Ready'}
            </div>
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 h-[calc(100vh-8rem)]">

          <div className="lg:col-span-4 flex flex-col gap-6 h-full overflow-y-auto pr-2 custom-scrollbar">
            <div className="bg-slate-900 rounded-xl p-6 border border-slate-800 shadow-xl">
              <div className="flex items-center gap-2 mb-6">
                <Zap className="w-5 h-5 text-amber-400" />
                <h2 className="text-lg font-semibold text-white">Definition Generator</h2>
              </div>

              <form onSubmit={handleGenerate} className="flex flex-col gap-5">
                <div>
                  <label htmlFor="term" className="block text-sm font-medium text-slate-400 mb-2">
                    Term Name <span className="text-red-400">*</span>
                  </label>
                  <input
                    type="text"
                    id="term"
                    value={term}
                    onChange={(e) => setTerm(e.target.value)}
                    placeholder="e.g. Cavitation, P-F Interval"
                    className="w-full bg-slate-800 border border-slate-700 rounded-lg px-4 py-3 text-white placeholder-slate-500 focus:ring-2 focus:ring-blue-500 focus:border-transparent transition-all outline-none"
                    required
                  />
                </div>

                <div>
                  <label htmlFor="definition" className="block text-sm font-medium text-slate-400 mb-2">
                    Draft Definition / Context
                  </label>
                  <textarea
                    id="definition"
                    value={draftDefinition}
                    onChange={(e) => setDraftDefinition(e.target.value)}
                    rows={6}
                    placeholder="Briefly describe the term. The AI will standardize it to ISO norms."
                    className="w-full bg-slate-800 border border-slate-700 rounded-lg px-4 py-3 text-white placeholder-slate-500 focus:ring-2 focus:ring-blue-500 focus:border-transparent transition-all outline-none resize-none"
                  />
                </div>

                <div className="flex gap-3 mt-2">
                  <Button 
                    type="submit" 
                    className="flex-1" 
                    isLoading={status === GeneratorStatus.GENERATING}
                    icon={<Zap size={18} />}
                  >
                    Generate Entry
                  </Button>
                  <Button 
                    type="button" 
                    variant="secondary"
                    onClick={clearForm}
                    disabled={status === GeneratorStatus.GENERATING}
                  >
                    Clear
                  </Button>
                </div>
              </form>
            </div>

            {history.length > 0 && (
              <div className="bg-slate-900 rounded-xl p-6 border border-slate-800 shadow-xl flex-1 min-h-[200px]">
                <div className="flex items-center gap-2 mb-4">
                  <History className="w-5 h-5 text-slate-400" />
                  <h2 className="text-md font-semibold text-slate-200">Recent Generations</h2>
                </div>
                <ul className="space-y-2">
                  {history.map((item) => (
                    <li key={item.id}>
                      <button
                        onClick={() => loadFromHistory(item)}
                        className="w-full text-left px-3 py-2 rounded hover:bg-slate-800 transition-colors flex justify-between items-center group"
                      >
                        <span className="text-sm text-slate-300 group-hover:text-white truncate">{item.term}</span>
                        <span className="text-xs text-slate-500 font-mono">
                           {new Date(item.timestamp).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}
                        </span>
                      </button>
                    </li>
                  ))}
                </ul>
              </div>
            )}
          </div>

          <div className="lg:col-span-8 flex flex-col h-full">
            {error && (
              <div className="mb-4 bg-red-900/20 border border-red-800 rounded-lg p-5 flex flex-col gap-4">
                <div className="flex items-start gap-3">
                  <AlertCircle className="w-5 h-5 text-red-500 mt-0.5 flex-shrink-0" />
                  <div>
                    <h3 className="text-sm font-semibold text-red-400">Quota Limit Exceeded (429)</h3>
                    <p className="text-sm text-red-300 mt-1 leading-relaxed">
                      {error}
                    </p>
                  </div>
                </div>
                <div className="flex flex-wrap gap-3 mt-2">
                  <Button 
                    variant="primary" 
                    size="sm" 
                    onClick={handleSelectKey}
                    icon={<Key size={14} />}
                    className="text-xs"
                  >
                    Set Personal API Key
                  </Button>
                  <Button 
                    variant="secondary" 
                    size="sm" 
                    onClick={() => handleGenerate()}
                    className="text-xs"
                  >
                    Retry Now
                  </Button>
                  <a 
                    href="https://ai.google.dev/gemini-api/docs/billing" 
                    target="_blank" 
                    rel="noopener noreferrer"
                    className="flex items-center gap-1 text-xs text-slate-400 hover:text-white transition-colors"
                  >
                    <Info size={14} />
                    Billing Documentation
                  </a>
                </div>
              </div>
            )}

            {result ? (
